Lemma hz_sh0_ec : forall m A, rw_cells bsegs m A hz_sh0 -> rw_cells bsegs m (A + 8) [CB 3 (poison_bytes 3 0)].
Proof.
  intros m A SH. unfold hz_sh0, hz_sh in SH.
  apply (rw_cells_nth_chunk m A [_; _; _] _ _) in SH. cbn [cells_size csize Nat.add] in SH.
  replace (A + Z.of_nat 8) with (A + 8) in SH by lia. exact SH.
Qed.
Lemma hz_sh0b_fb : forall m A, rw_cells bsegs m A hz_sh0b -> rw_cells bsegs m (A + 16) [CB 6 (poison_bytes 6 0)].
Proof.
  intros m A SH. unfold hz_sh0b, hz_sh in SH.
  apply (rw_cells_nth_chunk m A [_; _; _; _; _] _ _) in SH. cbn [cells_size csize Nat.add] in SH.
  replace (A + Z.of_nat 16) with (A + 16) in SH by lia. exact SH.
Qed.

